head.script:
// 전역 프로젝트 데이터 저장
scwin.projectList = [];
scwin.dynamicEventHandlers = {};
scwin.dynamicComponents = []; // 동적으로 생성된 컴포넌트들을 관리

scwin.onpageload = function() {
    // 기본적으로 대시보드 선택 상태로 설정
    scwin.changeSelectedMenu("dashboard");

    // 사용자 정보가 있으면 프로젝트 목록 조회
    scwin.loadUserProjects();
};

// 사용자 정보 설정 및 프로젝트 목록 로드
scwin.setUserInfo = function(userId) {
    console.log("사용자 정보 설정:", userId);
    dm_sideMenu.set("userName", userId);
    dmp_projectVo.set("userId", userId);
    scwin.loadUserProjects();
};

// 사용자의 프로젝트 목록 조회
scwin.loadUserProjects = function() {
    const userId = dm_sideMenu.get("userName");

    if (!userId) {
        console.log("사용자 정보가 없어 프로젝트 목록을 조회하지 않습니다.");
        return;
    }

    console.log("프로젝트 목록 조회 시작:", userId);
    dmp_projectVo.set("userId", userId);
    dmp_projectVo.set("pageIndex", "1");
    dmp_projectVo.set("pageSize", "100");

    // 서버통신 - 프로젝트 목록 조회
    $c.sbm.execute($p, sbm_selectProjectList);
};

// 프로젝트 목록 조회 완료 후 처리 (개선된 버전)
scwin.sbm_selectProjectList_submitdone = function(e) {
    console.log("프로젝트 목록 조회 완료:", e);

    // error 수신시
    const elData = e.responseJSON.elData;
    const elHeader = e.responseJSON.elHeader;
    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        console.error("프로젝트 목록 조회 오류 - 에러코드: " + (elHeader ? elHeader.resCode : "unknown") + ", 에러메시지: " + (elHeader ? elHeader.resMsg : "unknown"));
        // 에러가 발생해도 기본 프로젝트 메뉴는 표시
        scwin.renderDefaultProjects();
        return;
    }

    // 프로젝트 목록을 전역 변수에 저장
    scwin.projectList = elData.projectVoList || [];

    // 프로젝트 목록을 사이드메뉴에 동적으로 렌더링
    scwin.renderProjectMenus(scwin.projectList);

    // 메인 콘텐츠에도 프로젝트 데이터 전달
    scwin.notifyMainContentWithProjectData();
};

// 메인 콘텐츠에 프로젝트 데이터 전달
scwin.notifyMainContentWithProjectData = function() {
    try {
        if (parent && parent.wfr_mainContent && parent.wfr_mainContent.getWindow) {
            const mainContentWindow = parent.wfr_mainContent.getWindow();
            if (mainContentWindow && mainContentWindow.scwin && mainContentWindow.scwin.updateProjectDataFromSideMenu) {
                mainContentWindow.scwin.updateProjectDataFromSideMenu(scwin.projectList);
                console.log("메인 콘텐츠에 프로젝트 데이터 전달 완료:", scwin.projectList.length, "개");
            }
        }
    } catch(e) {
        console.log("메인 콘텐츠에 프로젝트 데이터 전달 중 오류:", e);
    }
};

// 기본 프로젝트 메뉴 렌더링 (데이터가 없을 때) - $p.dynamicCreate 사용
scwin.renderDefaultProjects = function() {
    // 기존 프로젝트 메뉴들 제거
    scwin.clearProjectMenus();

    try {
        // $p.dynamicCreate로 기본 메시지 표시
        const noProjectsMessage = $p.dynamicCreate(
            "grp_noProjects",
            "group",
            {
                style: "padding:12px 24px;margin:0 16px 8px 16px;"
            },
            grp_projectList
        );

        const messageText = $p.dynamicCreate(
            "txt_noProjects",
            "output",
            {
                style: "color:#666;font-style:italic;font-size:14px;"
            },
            noProjectsMessage
        );

        messageText.setValue("참여 중인 프로젝트가 없습니다.");

        // 생성된 컴포넌트 저장
        if (!scwin.dynamicComponents) {
            scwin.dynamicComponents = [];
        }
        scwin.dynamicComponents.push({
            menuGroup: noProjectsMessage,
            projectText: messageText,
            projectId: "no_projects"
        });

        console.log("기본 프로젝트 메뉴 렌더링 완료 ($p.dynamicCreate)");
    } catch(e) {
        console.error("기본 프로젝트 메뉴 렌더링 오류:", e);
    }
};

// 프로젝트 메뉴들을 동적으로 렌더링 ($p.dynamicCreate 사용)
scwin.renderProjectMenus = function(projectList) {
    console.log("프로젝트 메뉴 렌더링:", projectList);

    // 기존 프로젝트 메뉴들 제거
    scwin.clearProjectMenus();

    if (!projectList || projectList.length === 0) {
        scwin.renderDefaultProjects();
        return;
    }

    try {
        // $p.dynamicCreate를 사용하여 프로젝트 메뉴 생성
        for (let i = 0; i < projectList.length; i++) {
            const project = projectList[i];
            scwin.createProjectMenuItem(project, i);
        }

        console.log("$p.dynamicCreate 방식으로 프로젝트 메뉴 생성 완료");

    } catch(e) {
        console.error("프로젝트 메뉴 렌더링 오류:", e);
    }
};

// $p.dynamicCreate로 개별 프로젝트 메뉴 아이템 생성
scwin.createProjectMenuItem = function(project, index) {
    const projectId = project.projectId;
    const menuId = "grp_dynamic_project_" + projectId;
    const textId = "txt_project_" + projectId;
    const activeBarId = "grp_active_bar_" + projectId;

    try {
        // 1. 메뉴 아이템 컨테이너 그룹 생성
        const menuGroup = $p.dynamicCreate(
            menuId,
            "group",
            {
                style: "padding:12px 24px;margin-bottom:8px;cursor:pointer;background-color:transparent;border-radius:10px;margin:0 16px 8px 16px;position:relative;",
                className: "dynamic-project-menu"
            },
            grp_projectList
        );

        // 2. 선택 표시 바 생성
        const activeBar = $p.dynamicCreate(
            activeBarId,
            "group",
            {
                style: "position:absolute;left:0;top:50%;transform:translateY(-50%);width:3px;height:24px;background-color:#ffb823;display:none;",
                className: "project-active-bar"
            },
            menuGroup
        );

        // 3. 프로젝트 이름 텍스트 생성
        const projectText = $p.dynamicCreate(
            textId,
            "output",
            {
                style: "color:#000000;font-size:24px;font-family:Inter,sans-serif;font-weight:400;margin-left:8px;"
            },
            menuGroup
        );

        // 프로젝트 이름 설정
        projectText.setValue(project.projectName || "프로젝트 " + (index + 1));

        // 4. 클릭 이벤트 바인딩
        menuGroup.bind("onclick", function() {
            scwin.onProjectMenuClick(project);
        });

        // 생성된 컴포넌트들을 전역 객체에 저장 (나중에 제거하기 위해)
        if (!scwin.dynamicComponents) {
            scwin.dynamicComponents = [];
        }
        scwin.dynamicComponents.push({
            menuGroup: menuGroup,
            activeBar: activeBar,
            projectText: projectText,
            projectId: projectId
        });

        console.log("프로젝트 메뉴 아이템 생성 완료:", project.projectName);

    } catch(e) {
        console.error("프로젝트 메뉴 아이템 생성 오류:", e);
    }
};

// 프로젝트 메뉴 이벤트 리스너 등록 ($p.dynamicCreate로 생성된 컴포넌트는 이미 이벤트가 바인딩됨)
scwin.attachProjectEventListeners = function() {
    // $p.dynamicCreate로 생성할 때 이미 이벤트가 바인딩되므로 이 함수는 더 이상 필요하지 않음
    console.log("프로젝트 메뉴 이벤트 리스너는 이미 바인딩됨 ($p.dynamicCreate)");
};

// 기존 프로젝트 메뉴들 제거 (간소화)
scwin.clearProjectMenus = function() {
    try {
        if (scwin.dynamicComponents && scwin.dynamicComponents.length > 0) {
            // 동적으로 생성된 컴포넌트들 제거
            for (let i = 0; i < scwin.dynamicComponents.length; i++) {
                const component = scwin.dynamicComponents[i];
                if (component.menuGroup && component.menuGroup.remove) {
                    component.menuGroup.remove();
                }
            }
            scwin.dynamicComponents = [];
            console.log("동적 프로젝트 메뉴 컴포넌트들 제거 완료");
        }

        console.log("프로젝트 메뉴 정리 완룜");
    } catch(e) {
        console.error("프로젝트 메뉴 정리 오류:", e);
    }
};

// 프로젝트 메뉴 클릭 이벤트 처리
scwin.onProjectMenuClick = function(project) {
    console.log("프로젝트 메뉴 클릭:", project);

    const menuKey = "project_" + project.projectId;
    scwin.changeSelectedMenu(menuKey);

    // 부모 창의 메뉴 변경 함수 호출
    try {
        const parentFrame = $p.parent();

        if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출:", menuKey);
            parentFrame.scwin.changeMenu(menuKey, project);
        } else if (parent && parent.scwin && parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출 (parent):", menuKey);
            parent.scwin.changeMenu(menuKey, project);
        } else if (window.parent && window.parent.scwin && window.parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출 (window.parent):", menuKey);
            window.parent.scwin.changeMenu(menuKey, project);
        } else {
            console.error("부모 창의 changeMenu 함수를 찾을 수 없습니다.");
        }
    } catch(e) {
        console.error("부모 창 메뉴 변경 오류:", e);
    }
};

// 메뉴 클릭 이벤트
scwin.menu_dashboard_onclick = function(e) {
    console.log("=== 대시보드 메뉴 클릭 ===");
    scwin.changeSelectedMenu("dashboard");
    // 부모 창의 메뉴 변경 함수 호출
    try {
        const parentFrame = $p.parent();

        if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출 시작 ($p.parent)");
            parentFrame.scwin.changeMenu("dashboard");
            console.log("부모 changeMenu 함수 호출 완료");
        } else if (parent && parent.scwin && parent.scwin.changeMenu) {
            console.log("부모 changeMenu 함수 호출 시작 (parent)");
            parent.scwin.changeMenu("dashboard");
            console.log("부모 changeMenu 함수 호출 완료");
        } else {
            const winParent = window.parent;

            if (winParent && winParent.scwin && winParent.scwin.changeMenu) {
                console.log("부모 changeMenu 함수 호출 시작 (window.parent)");
                winParent.scwin.changeMenu("dashboard");
                console.log("부모 changeMenu 함수 호출 완료");
            } else {
                console.error("부모 창의 changeMenu 함수를 찾을 수 없습니다.");
            }
        }
    } catch(e) {
        console.error("부모 창 메뉴 변경 오류:", e);
    }
};

// 선택된 메뉴 스타일 변경 ($p.dynamicCreate로 생성된 컴포넌트 대응)
scwin.changeSelectedMenu = function(selectedMenu) {
    try {
        console.log("메뉴 선택 변경 시작:", selectedMenu);

        // 기존 선택 해제
        grp_dashboard.removeClass("selected-menu");
        grp_dashboard.setStyle("background-color", "transparent");
        grp_activeBar_dashboard.hide();

        // 모든 동적 프로젝트 메뉴의 선택 해제
        if (scwin.dynamicComponents && scwin.dynamicComponents.length > 0) {
            for (let i = 0; i < scwin.dynamicComponents.length; i++) {
                const component = scwin.dynamicComponents[i];
                if (component.menuGroup && component.activeBar) {
                    component.menuGroup.setStyle("background-color", "transparent");
                    component.activeBar.hide();
                }
            }
        }

        // 선택된 메뉴에만 스타일 적용
        if (selectedMenu === "dashboard") {
            grp_dashboard.addClass("selected-menu");
            grp_dashboard.setStyle("background-color", "rgba(255,184,35,0.2)");
            grp_activeBar_dashboard.show();
        } else if (selectedMenu.indexOf("project_") === 0) {
            // 동적 프로젝트 메뉴 선택
            const projectId = selectedMenu.replace("project_", "");

            // 해당 프로젝트의 컴포넌트 찾기
            if (scwin.dynamicComponents) {
                for (let i = 0; i < scwin.dynamicComponents.length; i++) {
                    const component = scwin.dynamicComponents[i];
                    if (component.projectId === projectId) {
                        component.menuGroup.setStyle("background-color", "rgba(255,184,35,0.2)");
                        component.activeBar.show();
                        break;
                    }
                }
            }
        }

        console.log("메뉴 선택 완료:", selectedMenu);

        // 데이터맵에도 선택된 메뉴 저장
        dm_sideMenu.set("selectedMenu", selectedMenu);
    } catch(e) {
        console.log("메뉴 스타일 변경 오류:", e);
    }
};

// 부모에서 호출할 수 있는 메뉴 업데이트 함수
scwin.updateSelectedMenu = function(menuType) {
    scwin.changeSelectedMenu(menuType);
};

// 외부에서 프로젝트 메뉴를 선택할 수 있는 함수 (메인 콘텐츠의 프로젝트 카드 클릭용)
scwin.selectProjectMenuFromExternal = function(projectId, projectData) {
    console.log("외부에서 프로젝트 메뉴 선택 요청:", projectId, projectData);

    const menuKey = "project_" + projectId;

    // 메뉴 선택 상태 변경
    scwin.changeSelectedMenu(menuKey);

    // 프로젝트 메뉴 클릭 이벤트 처리
    if (projectData) {
        scwin.onProjectMenuClick(projectData);
    }
};

// 프로젝트 추가 후 목록 새로고침
scwin.refreshProjectList = function() {
    console.log("프로젝트 목록 새로고침");
    scwin.loadUserProjects();

    // 메인 콘텐츠에도 즉시 갱신 요청
    setTimeout(() => {
        scwin.notifyMainContentWithProjectData();
    }, 500);
};

scwin.btn_addProject_onclick = function(e) {
    console.log("=== 프로젝트 추가 버튼 클릭 ===");

    try {
        // 부모 창의 모달 열기 함수 호출
        const parentFrame = $p.parent();

        if (parentFrame && parentFrame.scwin && parentFrame.scwin.openProjectAddModal) {
            console.log("부모 openProjectAddModal 함수 호출 ($p.parent)");
            parentFrame.scwin.openProjectAddModal();
        } else if (parent && parent.scwin && parent.scwin.openProjectAddModal) {
            console.log("부모 openProjectAddModal 함수 호출 (parent)");
            parent.scwin.openProjectAddModal();
        } else if (window.parent && window.parent.scwin && window.parent.scwin.openProjectAddModal) {
            console.log("부모 openProjectAddModal 함수 호출 (window.parent)");
            window.parent.scwin.openProjectAddModal();
        } else {
            console.error("부모 창의 openProjectAddModal 함수를 찾을 수 없습니다.");
            alert("프로젝트 추가 모달을 열 수 없습니다.");
        }
    } catch(e) {
        console.error("프로젝트 추가 모달 열기 오류:", e);
        alert("프로젝트 추가 모달 열기 중 오류가 발생했습니다.");
    }
};
